  1	//! Write-path tools: `apply_patch` and `write_file`.
  2	//!
  3	//! These are registered **only** when the CLI is invoked with `--write`.
  4	//! They are scoped to the enclosing git repository via [`SourceTree`]:
  5	//! escapes, git-ignored paths, `.ignore`, and anything under `.git/` are
  6	//! refused. Changes land as local git commits — never pushed. Git is the
  7	//! undo button and the audit trail.
  8	
  9	use std::path::Path;
 10	use std::process::Stdio;
 11	use std::sync::Arc;
 12	
 13	use rig::tool::{PortableDynamicTool, ToolExecutionError, ToolOutput};
 14	use serde_json::json;
 15	use tokio::io::AsyncWriteExt as _;
