 25	/// Run `git` with `args` in `root`, with the scrubbed environment, capturing
 26	/// output. Returns `Ok((stdout, stderr))` on success, `Err(message)` on
 27	/// failure (the more informative of stdout/stderr, trimmed).
 28	async fn git_run(root: &Path, args: &[&str]) -> Result<(String, String), String> {
 29	    let mut cmd = tokio::process::Command::new("git");
 30	    cmd.current_dir(root);
 31	    cmd.env_clear();
 32	    for (k, v) in scrubbed_env() {
 33	        cmd.env(k, v);
 34	    }
 35	    cmd.stdin(Stdio::null());
 36	    cmd.stdout(Stdio::piped());
 37	    cmd.stderr(Stdio::piped());
 38	    cmd.args(args);
 39	    let output = cmd
 40	        .output()
 41	        .await
 42	        .map_err(|e| format!("spawn git {}: {e}", args[0]))?;
 43	    let stdout = String::from_utf8_lossy(&output.stdout).into_owned();
 44	    let stderr = String::from_utf8_lossy(&output.stderr).into_owned();
 45	    if !output.status.success() {
 46	        let msg = if stderr.trim().is_empty() {
 47	            stdout.trim()
 48	        } else {
 49	            stderr.trim()
 50	        };
 51	        return Err(msg.to_string());
 52	    }
 53	    Ok((stdout, stderr))
 54	}
