 56	/// Run `git apply` over the diff on stdin with the given extra args,
 57	/// returning `Ok(())` on success or the trimmed git error.
 58	async fn git_apply(root: &Path, diff: &str, extra: &[&str]) -> Result<(), String> {
 59	    let mut cmd = tokio::process::Command::new("git");
 60	    cmd.current_dir(root);
 61	    cmd.env_clear();
 62	    for (k, v) in scrubbed_env() {
 63	        cmd.env(k, v);
 64	    }
 65	    cmd.stdin(Stdio::piped());
 66	    cmd.stdout(Stdio::piped());
 67	    cmd.stderr(Stdio::piped());
 68	    cmd.arg("apply");
 69	    cmd.args(extra);
 70	    cmd.arg("-");
 71	
 72	    let mut child = cmd.spawn().map_err(|e| format!("spawn git apply: {e}"))?;
 73	    let mut stdin = child.stdin.take().ok_or("git apply stdin unavailable")?;
 74	    stdin
 75	        .write_all(diff.as_bytes())
 76	        .await
 77	        .map_err(|e| format!("writing diff to git apply: {e}"))?;
 78	    drop(stdin); // EOF
 79	
 80	    let output = child
 81	        .wait_with_output()
 82	        .await
 83	        .map_err(|e| format!("waiting for git apply: {e}"))?;
 84	    if !output.status.success() {
 85	        let stderr = String::from_utf8_lossy(&output.stderr);
 86	        let stdout = String::from_utf8_lossy(&output.stdout);
 87	        let msg = if stderr.trim().is_empty() {
 88	            stdout.trim()
 89	        } else {
 90	            stderr.trim()
 91	        };
 92	        return Err(msg.to_string());
 93	    }
 94	    Ok(())
 95	}
