 97	/// Apply a unified diff to the repo with `git apply --3way --recount`.
 98	///
 99	/// Why `--3way`: `git apply` without it matches hunk context strictly
100	/// against the working tree, so a hand-written patch fails with "patch does
101	/// not apply" the moment the target file carries any uncommitted edit — the
102	/// normal state during the agent's self-improvement loop, and the reason the
103	/// old dirty-target guard refused almost every call.
104	///
105	/// `--3way` instead merges the patch against the blob recorded in the index
106	/// (what the worktree was based on), so the patch applies cleanly on top of
107	/// unrelated uncommitted changes. `--recount` recomputes hunk line counts
108	/// from the body, tolerating slightly off `@@ -a,b +c,d @@` numbers in
109	/// hand-composed diffs.
110	///
111	/// Git applies atomically (nothing is written unless every file applies), so
112	/// a failure leaves the working tree untouched; the precise git error is
113	/// surfaced so the model can fix the patch. There is no "tree must be clean"
114	/// refusal here — that was the source of the near-total failure rate.
115	async fn git_apply_diff(root: &Path, diff: &str) -> Result<(), String> {
116	    git_apply(root, diff, &["--3way", "--recount"])
117	        .await
118	        .map_err(|msg| format!("git apply failed: {msg}"))?;
119	    Ok(())
120	}
