122	/// Is the patch's change already present in the working tree? Git applies
123	/// the reversed diff cleanly exactly when the current tree already contains
124	/// the result the patch produces — the genuinely useful signal the old
125	/// dirty-target guard was really after ("the change already exists, stop
126	/// re-patching it").
127	#[allow(dead_code)]
128	async fn diff_already_applied(root: &Path, diff: &str) -> bool {
129	    git_apply(root, diff, &["--check", "--reverse", "--recount"])
130	        .await
131	        .is_ok()
132	}
