134	/// Extract the repo-relative path from a `--- a/…` or `+++ b/…` line,
135	/// stripping any trailing tab metadata (timestamps from `git diff`).
136	fn diff_path_from_marker(rest: &str) -> String {
137	    rest.split('\t').next().unwrap_or(rest).trim().to_string()
138	}
139	
140	/// Reject diffs that touch protected paths (`.ignore`, `.git*`).
141	fn diff_touches_protected(diff: &str) -> Option<String> {
142	    for line in diff.lines() {
143	        for prefix in ["+++ b/", "--- a/"] {
144	            if let Some(rest) = line.strip_prefix(prefix) {
145	                let rel = diff_path_from_marker(rest);
146	                if is_protected(&rel) {
147	                    return Some(rel);
148	                }
149	            }
150	        }
151	    }
152	    None
153	}
