155	/// Tool: apply a unified diff to the repository working tree.
156	pub fn builtin_apply_patch(tree: Arc<SourceTree>) -> PortableDynamicTool {
157	    PortableDynamicTool::new(
158	        "apply_patch",
159	        "Apply a unified diff (git diff format) to the repository working tree. Applies with \
160	         `git apply --3way --recount`, merging the patch against the index so it works on top \
161	         of other uncommitted changes — no need for a clean tree first. On failure git's exact \
162	         error is returned. If `message` is given, the change is committed with that message. \
163	         Diffs that touch `.ignore` or `.git*` paths are refused. Changes are local commits \
164	         only — never pushed.",
165	        json!({
166	            "type": "object",
167	            "properties": {
168	                "diff": {
169	                    "type": "string",
170	                    "description": "Unified diff against the current working tree"
171	                },
172	                "message": {
173	                    "type": "string",
174	                    "description": "Optional commit message"
175	                }
176	            },
177	            "required": ["diff"]
178	        }),
179	        move |args: serde_json::Value| {
180	            let tree = tree.clone();
181	            Box::pin(async move {
182	                let diff = args
183	                    .get("diff")
184	                    .and_then(|v| v.as_str())
185	                    .ok_or_else(|| ToolExecutionError::invalid_args("missing string field 'diff'"))?
186	                    .to_string();
187	                let message = args
188	                    .get("message")
189	                    .and_then(|v| v.as_str())
190	                    .filter(|m| !m.trim().is_empty())
191	                    .map(String::from);
192	
193	                if let Some(rel) = diff_touches_protected(&diff) {
194	                    return Err(ToolExecutionError::permission_denied(format!(
195	                        "diff touches protected path: {rel}"
196	                    )));
197	                }
198	
199	                git_apply_diff(tree.root(), &diff)
200	                    .await
201	                    .map_err(ToolExecutionError::provider)?;
202	
203	                let mut out = String::from("patch applied");
204	                if let Some(msg) = message {
205	                    // `git apply` only touches the working tree; stage
206	                    // everything so the commit captures the patch (this also
207	                    // covers new files and initial commits).
208	                    git_run(tree.root(), &["add", "-A"])
209	                        .await
210	                        .map_err(ToolExecutionError::provider)?;
211	                    let (_, stderr) = git_run(tree.root(), &["commit", "-m", &msg])
212	                        .await
213	                        .map_err(ToolExecutionError::provider)?;
214	                    let note = if stderr.trim().is_empty() {
215	                        "committed".to_string()
216	                    } else {
217	                        format!("committed ({})", stderr.trim())
218	                    };
219	                    out.push_str(&format!("\n{note}"));
220	                }
221	                Ok(ToolOutput::text(out))
222	            })
223	        },
224	    )
225	}
