227	/// Tool: write a text file inside the repository.
228	pub fn builtin_write_file(tree: Arc<SourceTree>) -> PortableDynamicTool {
229	    PortableDynamicTool::new(
230	        "write_file",
231	        "Write a text file inside the git repository. `path` is relative to the repo root. \
232	         Refused: paths outside the repo, git-ignored paths, `.ignore`, `.gitignore`, anything \
233	         under `.git/`. If `message` is given, the change is committed with that message. \
234	         Local commits only — never pushed.",
235	        json!({
236	            "type": "object",
237	            "properties": {
238	                "path": {
239	                    "type": "string",
240	                    "description": "Path relative to the repo root"
241	                },
242	                "content": {
243	                    "type": "string",
244	                    "description": "Full file contents"
245	                },
246	                "message": {
247	                    "type": "string",
248	                    "description": "Optional commit message"
249	                }
250	            },
251	            "required": ["path", "content"]
252	        }),
253	        move |args: serde_json::Value| {
254	            let tree = tree.clone();
255	            Box::pin(async move {
256	                let rel = args
257	                    .get("path")
258	                    .and_then(|v| v.as_str())
259	                    .ok_or_else(|| ToolExecutionError::invalid_args("missing string field 'path'"))?
260	                    .to_string();
261	                let content = args
262	                    .get("content")
263	                    .and_then(|v| v.as_str())
264	                    .ok_or_else(|| {
265	                        ToolExecutionError::invalid_args("missing string field 'content'")
266	                    })?
267	                    .to_string();
268	                let message = args
269	                    .get("message")
270	                    .and_then(|v| v.as_str())
271	                    .filter(|m| !m.trim().is_empty())
272	                    .map(String::from);
273	
274	                if is_protected(&rel) {
275	                    return Err(ToolExecutionError::permission_denied(format!(
276	                        "path is protected: {rel}"
277	                    )));
278	                }
279	
280	                // Escape/ignore checks via SourceTree (handles `..`, absolute
281	                // paths, symlink escapes, and ignore rules).
282	                let abs = tree
283	                    .resolve_for_write(Path::new(&rel))
284	                    .map_err(map_source_err)?;
285	                if tree.is_ignored(&abs) {
286	                    return Err(ToolExecutionError::permission_denied(format!(
287	                        "path is git-ignored: {}",
288	                        abs.display()
289	                    )));
290	                }
291	
292	                if let Some(parent) = abs.parent() {
293	                    std::fs::create_dir_all(parent).map_err(|e| {
294	                        ToolExecutionError::provider(format!("creating parent dirs: {e}"))
295	                    })?;
296	                }
297	                std::fs::write(&abs, &content).map_err(|e| {
298	                    ToolExecutionError::provider(format!("writing {}: {e}", abs.display()))
299	                })?;
300	
301	                let mut out = format!("wrote {} ({} bytes)", abs.display(), content.len());
302	                if let Some(msg) = message {
303	                    git_run(tree.root(), &["add", "--", &rel])
304	                        .await
305	                        .map_err(ToolExecutionError::provider)?;
306	                    let (_, stderr) = git_run(tree.root(), &["commit", "-m", &msg])
307	                        .await
308	                        .map_err(ToolExecutionError::provider)?;
309	                    let note = if stderr.trim().is_empty() {
310	                        "committed".to_string()
311	                    } else {
312	                        format!("committed ({})", stderr.trim())
313	                    };
314	                    out.push_str(&format!("\n{note}"));
315	                }
316	                Ok(ToolOutput::text(out))
317	            })
318	        },
319	    )
320	}
